  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "The closest analogue (Morgan 0.9014), a phenylethanoid glycoside nearly identical to the query, was detected in rat hippocampus and striatum after oral administration, directly demonstrating BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A closely related phenylethanoid glycoside (Morgan 0.7671) also crossed the BBB and was detected in rat brain after oral administration, independently supporting CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A structurally distant dicaffeoylquinic acid (Morgan 0.3537) showed very low mouse brain uptake (0.003% of dose), but its low similarity and different scaffold limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phenylethanoid glycoside closely matching high-similarity analogues that were directly detected in rat brain after oral administration. The strongest transferable in vivo evidence supports meaningful BBB/CNS access; the only poor-uptake record is structurally distant and does not override the high-similarity positives.",
  "evidence_gaps": [
    "No quantitative brain-to-plasma or CSF exposure ratio is available for the exact query molecule.",
    "Most supportive records are qualitative brain-tissue detection after oral administration, so the extent of CNS exposure is not precisely quantified.",
    "Potential contributions from metabolites or extract matrix cannot be fully excluded in some records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

